import { pudding, type JSONValue } from "@pudding/widget";
import { QueryClient } from "@tanstack/react-query";
import { z } from "zod";
import {
  accountSchema,
  itemIDSchema,
  parseItemID,
  viewerSchema,
  repoListSchema,
  installationsResponseSchema,
  installationReposResponseSchema,
  repoSummary,
  ghIssueSchema,
  ghIssueListSchema,
  commentListSchema,
  itemSummary,
  metaFromSummary,
  parseSearchQuery,
  matchesParsedQuery,
  readStore,
  cardFor,
  updateCards,
  saveDraft,
  statuses,
  draftSchema,
  updateSchema,
  type Update,
  type Card,
  type CardMeta,
  type ItemSummary,
  type RepoSummary,
} from "./model";
import { t, errorText } from "./text";

export const DEFAULT_QUERY = "is:open involves:@me";

// One controller/cache per guest binding. Shared cache requests own their
// cancellation signal so canceling one UI reader never aborts a shared request.
export function createGitHubBoard(client: QueryClient) {
  const known = new Set<string>();
  const metaCache = new Map<string, CardMeta>();

  const viewer = () =>
    client.fetchQuery({
      queryKey: ["github", "viewer"],
      queryFn: async () => {
        const res = await pudding.query("viewer");
        return accountSchema.parse(viewerSchema.parse(res.data).login);
      },
      staleTime: Infinity,
    });

  const ensure = async (account: string, signal?: AbortSignal) => {
    if ((await viewer()) !== accountSchema.parse(account)) {
      throw new Error("wrongAccount");
    }
    signal?.throwIfAborted();
  };

  const storage = async (signal?: AbortSignal) => {
    const raw = await pudding.storage.read({ signal });
    return { raw, store: readStore(raw.data.githubBoard) };
  };

  async function repos(
    account: string,
    page = 1,
    limit = 20,
    signal?: AbortSignal,
  ) {
    await ensure(account, signal);
    const items = await client.fetchQuery({
      queryKey: ["github", "repos", account, page, limit],
      staleTime: 60000,
      queryFn: async ({ signal: querySignal }) => {
        const merged = new Map<string, RepoSummary>();

        // 1. Standard /user/repos (works for PAT and user/collaborator/org_member repos)
        try {
          const directRaw = repoListSchema.parse(
            (
              await pudding.query(
                "repos",
                { page, limit },
                { signal: querySignal },
              )
            ).data,
          );
          for (const r of directRaw) {
            const sum = repoSummary(r);
            merged.set(sum.fullName, sum);
          }
        } catch {
          // Fall through to GitHub App installations discovery
        }

        // 2. GitHub App installations discovery (/user/installations -> /user/installations/{id}/repositories)
        if (page === 1) {
          try {
            const instRes = installationsResponseSchema.parse(
              (
                await pudding.query(
                  "installations",
                  { page: 1, limit: 10 },
                  { signal: querySignal },
                )
              ).data,
            );
            for (const inst of instRes.installations.slice(0, 3)) {
              const instRepos = installationReposResponseSchema.parse(
                (
                  await pudding.query(
                    "installationRepos",
                    { installationID: inst.id, page: 1, limit },
                    { signal: querySignal },
                  )
                ).data,
              );
              for (const r of instRepos.repositories) {
                const sum = repoSummary(r);
                if (!merged.has(sum.fullName)) {
                  merged.set(sum.fullName, sum);
                }
              }
            }
          } catch {
            // Ignore if token does not use GitHub App installations endpoint
          }
        }

        return [...merged.values()].sort(
          (a, b) => Date.parse(b.updatedAt || "0") - Date.parse(a.updatedAt || "0"),
        );
      },
    });
    signal?.throwIfAborted();
    return {
      account,
      page,
      hasNextPage: items.length >= limit,
      repos: items,
    };
  }

  async function fetchRepoItems(
    account: string,
    fullRepo: string,
    state: "open" | "closed" | "all",
    kind: "pr" | "issue" | "all",
    page: number,
    limit: number,
  ): Promise<ItemSummary[]> {
    const [owner, repo] = fullRepo.split("/");
    return client.fetchQuery({
      queryKey: [
        "github",
        "repoItems",
        account,
        fullRepo,
        state,
        kind,
        page,
        limit,
      ],
      staleTime: 60000,
      queryFn: async ({ signal: repoSignal }) => {
        if (kind === "pr") {
          const pulls = ghIssueListSchema.parse(
            (
              await pudding.query(
                "repoPulls",
                { owner, repo, state, page, limit },
                { signal: repoSignal },
              )
            ).data,
          );
          return pulls.map((p) => itemSummary(p, fullRepo, true));
        }

        try {
          const issuesAndPRs = ghIssueListSchema.parse(
            (
              await pudding.query(
                "repoIssues",
                { owner, repo, state, page, limit },
                { signal: repoSignal },
              )
            ).data,
          );
          if (issuesAndPRs.length > 0 || kind === "issue") {
            return issuesAndPRs.map((it) => itemSummary(it, fullRepo, false));
          }
        } catch {
          if (kind === "issue") return [];
        }

        const pulls = ghIssueListSchema.parse(
          (
            await pudding.query(
              "repoPulls",
              { owner, repo, state, page, limit },
              { signal: repoSignal },
            )
          ).data,
        );
        return pulls.map((p) => itemSummary(p, fullRepo, true));
      },
    });
  }

  async function searchPage(
    account: string,
    q = DEFAULT_QUERY,
    page = 1,
    limit = 20,
    signal?: AbortSignal,
  ) {
    await ensure(account, signal);
    const normalizedQ = q.trim() || DEFAULT_QUERY;
    const parsed = parseSearchQuery(normalizedQ, account);

    let targetRepos: string[] = [];
    if (parsed.repo) {
      targetRepos = [parsed.repo];
    } else {
      const repoList = await repos(account, 1, 20, signal);
      targetRepos = repoList.repos.slice(0, 3).map((r) => r.fullName);
    }

    if (targetRepos.length === 0) {
      return {
        q: normalizedQ,
        page,
        totalCount: 0,
        items: [] as ItemSummary[],
        hasNextPage: false,
      };
    }

    const perRepoLists = await Promise.all(
      targetRepos.map((rName) =>
        fetchRepoItems(account, rName, parsed.state, parsed.kind, page, limit),
      ),
    );
    signal?.throwIfAborted();

    const mergedMap = new Map<string, ItemSummary>();
    for (const list of perRepoLists) {
      for (const it of list) {
        metaCache.set(it.id, metaFromSummary(it));
        if (matchesParsedQuery(it, parsed)) {
          mergedMap.set(it.id, it);
        }
      }
    }

    const sorted = [...mergedMap.values()].sort(
      (a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt),
    );
    const items = sorted.slice(0, limit);
    items.forEach((x) => known.add(x.id));

    const hasNextPage = perRepoLists.some((l) => l.length === limit);
    return {
      q: normalizedQ,
      page,
      totalCount: sorted.length,
      items,
      hasNextPage,
    };
  }

  async function list(
    account: string,
    q = DEFAULT_QUERY,
    page = 1,
    limit = 20,
    signal?: AbortSignal,
  ) {
    const p = await searchPage(account, q, page, limit, signal);
    const s = await storage(signal);
    const items = p.items.map((item) => {
      const c = cardFor(s.store, account, item.id);
      return {
        ...item,
        status: c.status,
        followUpAt: c.followUpAt,
        hasDraft: Boolean(c.draft),
        note: c.note,
      };
    });

    const accountCards = s.store.accounts[account] ?? {};
    const pageItemsMap = new Map(items.map((item) => [item.id, item]));

    const taggedCards = Object.entries(accountCards)
      .filter(
        ([_, c]) =>
          c.status !== "triage" ||
          Boolean(c.draft) ||
          Boolean(c.note) ||
          Boolean(c.followUpAt),
      )
      .map(([id, c]) => {
        known.add(id);
        const fromPage = pageItemsMap.get(id);
        const cached = metaCache.get(id);
        const parsedId = parseItemID(id);
        return {
          id,
          repo: `${parsedId.owner}/${parsedId.repo}`,
          number: parsedId.number,
          kind: c.meta?.kind ?? fromPage?.kind ?? cached?.kind ?? ("issue" as const),
          title:
            c.meta?.title ||
            fromPage?.title ||
            cached?.title ||
            t("untitled"),
          state: c.meta?.state ?? fromPage?.state ?? cached?.state ?? "open",
          isDraftPR:
            c.meta?.isDraftPR ??
            fromPage?.isDraftPR ??
            cached?.isDraftPR ??
            false,
          author:
            c.meta?.author ||
            fromPage?.author ||
            cached?.author ||
            account,
          labels: c.meta?.labels ?? fromPage?.labels ?? cached?.labels ?? [],
          assignees: fromPage?.assignees ?? [],
          requestedReviewers: fromPage?.requestedReviewers ?? [],
          commentCount:
            c.meta?.commentCount ??
            fromPage?.commentCount ??
            cached?.commentCount ??
            0,
          updatedAt:
            c.meta?.updatedAt ||
            fromPage?.updatedAt ||
            cached?.updatedAt ||
            new Date().toISOString(),
          snippet:
            c.meta?.snippet ?? fromPage?.snippet ?? cached?.snippet ?? "",
          status: c.status,
          note: c.note,
          followUpAt: c.followUpAt,
          hasDraft: Boolean(c.draft),
        };
      });

    return {
      account,
      q: p.q,
      page: p.page,
      totalCount: p.totalCount,
      hasNextPage: p.hasNextPage,
      items,
      taggedCards,
      storageVersion: s.raw.version,
    };
  }

  async function board(signal?: AbortSignal) {
    const account = await viewer();
    const p = await list(account, DEFAULT_QUERY, 1, 20, signal);
    return {
      account,
      query: p.q,
      counts: {
        triage: p.items.filter((x) => x.status === "triage").length,
        review: p.taggedCards.filter((x) => x.status === "review").length,
        inProgress: p.taggedCards.filter((x) => x.status === "inProgress")
          .length,
        done: p.taggedCards.filter((x) => x.status === "done").length,
      },
      countScope: "first search page and saved board items",
      loadedCount: p.items.length,
      totalCount: p.totalCount,
      hasNextPage: p.hasNextPage,
      storageVersion: p.storageVersion,
    };
  }

  async function read(
    account: string,
    id: string,
    commentPage = 1,
    commentLimit = 10,
    signal?: AbortSignal,
  ) {
    await ensure(account, signal);
    const { owner, repo, number } = parseItemID(id);
    const fullRepo = `${owner}/${repo}`;

    const [issue, comments] = await Promise.all([
      client.fetchQuery({
        queryKey: ["github", "detail", account, fullRepo, number],
        staleTime: 60000,
        queryFn: async ({ signal: detailSignal }) => {
          try {
            return ghIssueSchema.parse(
              (
                await pudding.query(
                  "itemDetail",
                  { owner, repo, number },
                  { signal: detailSignal },
                )
              ).data,
            );
          } catch {
            return ghIssueSchema.parse(
              (
                await pudding.query(
                  "pullDetail",
                  { owner, repo, number },
                  { signal: detailSignal },
                )
              ).data,
            );
          }
        },
      }),
      client.fetchQuery({
        queryKey: [
          "github",
          "comments",
          account,
          fullRepo,
          number,
          commentPage,
          commentLimit,
        ],
        staleTime: 60000,
        queryFn: async ({ signal: commentsSignal }) => {
          try {
            return commentListSchema.parse(
              (
                await pudding.query(
                  "itemComments",
                  {
                    owner,
                    repo,
                    number,
                    page: commentPage,
                    limit: commentLimit,
                  },
                  { signal: commentsSignal },
                )
              ).data,
            );
          } catch {
            return [];
          }
        },
      }),
    ]);

    if (issue.number !== number) throw new Error("Item number mismatch");
    signal?.throwIfAborted();

    const summary = itemSummary(issue, fullRepo);
    known.add(summary.id);
    metaCache.set(summary.id, metaFromSummary(summary));
    const s = await storage(signal);
    const rawBody = issue.body ?? "";

    return {
      account,
      ...summary,
      ...cardFor(s.store, account, summary.id),
      storageVersion: s.raw.version,
      body: rawBody.slice(0, 12000),
      bodyTruncated: rawBody.length > 12000,
      commentPage,
      hasNextCommentPage:
        comments.length === commentLimit &&
        commentPage * commentLimit < summary.commentCount,
      comments: comments.map((c) => {
        const text = c.body ?? "";
        return {
          id: String(c.id),
          author: c.user?.login ?? "unknown",
          createdAt: c.created_at,
          body: text.slice(0, 8000),
          truncated: text.length > 8000,
        };
      }),
    };
  }

  async function edit(
    account: string,
    expectedStorageVersion: number,
    updates: Update[],
    draft?: { id: string; value: Card["draft"] },
    signal?: AbortSignal,
  ) {
    await ensure(account, signal);
    const s = await storage(signal);
    if (s.raw.version !== expectedStorageVersion) throw new Error("conflict");
    let next = updates.length
      ? updateCards(s.store, account, updates, known, metaCache)
      : s.store;
    if (draft) {
      const validId = itemIDSchema.parse(draft.id);
      if (!known.has(validId)) throw new Error("unknownItem");
      next = saveDraft(next, account, validId, draft.value, metaCache);
    }
    const data = { ...s.raw.data, githubBoard: next as unknown as JSONValue };
    if (new TextEncoder().encode(JSON.stringify(data)).length > 262144) {
      throw new Error("storageLimit");
    }
    signal?.throwIfAborted();
    const saved = await pudding.storage.write({
      expectedVersion: expectedStorageVersion,
      data,
    });
    await client.invalidateQueries({ queryKey: ["github-board-view"] });
    return {
      account,
      changedIDs: [
        ...new Set([...updates.map((x) => x.id), ...(draft ? [draft.id] : [])]),
      ],
      storageVersion: saved.version,
    };
  }

  async function refresh(account: string, signal?: AbortSignal) {
    await ensure(account, signal);
    await client.invalidateQueries({
      queryKey: ["github"],
      refetchType: "none",
    });
    await client.invalidateQueries({
      queryKey: ["github-board-view"],
      refetchType: "none",
    });
    return board(signal);
  }

  return { viewer, repos, searchPage, list, board, read, edit, refresh };
}

export type GitHubBoard = ReturnType<typeof createGitHubBoard>;

export function registerInterfaces(gh: GitHubBoard) {
  const account = { account: accountSchema };
  const write = { ...account, expectedStorageVersion: z.number().int().min(0) };
  const wrap =
    <I, O>(run: (i: I, signal: AbortSignal) => Promise<O>) =>
    async (i: I, c: { signal: AbortSignal }) => {
      try {
        return await run(i, c.signal);
      } catch (e) {
        throw new Error(errorText(e));
      }
    };

  return [
    pudding.defineInterface({
      name: "getBoard",
      description: t("descBoard"),
      input: z.object({}).strict(),
      run: wrap((_, s) => gh.board(s)),
    }),
    pudding.defineInterface({
      name: "listRepos",
      description: t("descRepos"),
      input: z
        .object({
          ...account,
          page: z.number().int().min(1).max(50).default(1),
          limit: z.number().int().min(1).max(50).default(20),
        })
        .strict(),
      run: wrap(
        (i: { account: string; page: number; limit: number }, s) =>
          gh.repos(i.account, i.page, i.limit, s),
      ),
    }),
    pudding.defineInterface({
      name: "listItems",
      description: t("descList"),
      input: z
        .object({
          ...account,
          q: z.string().max(500).default(DEFAULT_QUERY),
          page: z.number().int().min(1).max(50).default(1),
          limit: z.number().int().min(1).max(30).default(20),
        })
        .strict(),
      run: wrap(
        (i: { account: string; q: string; page: number; limit: number }, s) =>
          gh.list(i.account, i.q, i.page, i.limit, s),
      ),
    }),
    pudding.defineInterface({
      name: "readItem",
      description: t("descRead"),
      input: z
        .object({
          ...account,
          id: itemIDSchema,
          commentPage: z.number().int().min(1).max(50).default(1),
          commentLimit: z.number().int().min(1).max(20).default(10),
        })
        .strict(),
      run: wrap(
        (
          i: {
            account: string;
            id: string;
            commentPage: number;
            commentLimit: number;
          },
          s,
        ) => gh.read(i.account, i.id, i.commentPage, i.commentLimit, s),
      ),
    }),
    pudding.defineInterface({
      name: "updateCards",
      description: t("descUpdate"),
      input: z
        .object({ ...write, updates: z.array(updateSchema).min(1).max(20) })
        .strict(),
      run: wrap(
        (
          i: {
            account: string;
            expectedStorageVersion: number;
            updates: Update[];
          },
          s,
        ) =>
          gh.edit(
            i.account,
            i.expectedStorageVersion,
            i.updates,
            undefined,
            s,
          ),
      ),
    }),
    pudding.defineInterface({
      name: "saveCommentDraft",
      description: t("descDraft"),
      input: z
        .object({
          ...write,
          id: itemIDSchema,
          draft: draftSchema.nullable(),
        })
        .strict(),
      run: wrap(
        (
          i: {
            account: string;
            expectedStorageVersion: number;
            id: string;
            draft: Card["draft"];
          },
          s,
        ) =>
          gh.edit(
            i.account,
            i.expectedStorageVersion,
            [],
            { id: i.id, value: i.draft },
            s,
          ),
      ),
    }),
    pudding.defineInterface({
      name: "refreshBoard",
      description: t("descRefresh"),
      input: z.object(account).strict(),
      run: wrap((i: { account: string }, s) => gh.refresh(i.account, s)),
    }),
  ];
}

