  --pr-color: light-dark(#7e22ce, #c084fc);
  --pr-bg: light-dark(#f3e8ff, #581c8740);
  --issue-color: light-dark(#15803d, #4ade80);
  --issue-bg: light-dark(#dcfce7, #14532d40);
  font:
    14px/1.5 -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
