  flex: 1;
  min-width: 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ghb-card > strong {
  font-size: 13px;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
}

.ghb-card > p {
  font-size: 12px;
  color: var(--muted);
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
}

.ghb-card-labels,
.ghb-labels-row {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.ghb-label-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 7px;
  border-radius: 999px;
  border: 1px solid var(--edge);
  background: var(--panel);
  font-size: 10.5px;
  color: var(--text);
}

.ghb-label-chip > i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--lbl-color, var(--muted));
}

.ghb-card footer {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-size: 11px;
  margin-top: 2px;
}

.ghb-meta-inline {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.ghb-meta-inline.is-accent {
  color: var(--accent);
}

.ghb-empty {
  padding: 28px 12px;
  color: var(--muted);
  text-align: center;
  font-size: 12px;
}

.ghb-page-info {
  padding: 0 12px;
  border-top: 1px solid var(--edge);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  height: 42px;
  flex-shrink: 0;
  color: var(--muted);
  font-size: 11.5px;
}

.ghb-pager {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ghb-pager button {
  padding: 4px 6px;
}

.ghb-reader-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 24px;
  color: var(--muted);
  font-size: 13px;
  text-align: center;
}

/* Right Detail Inspector */
.ghb-detail {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  background: var(--surface);
  color: var(--text);
  overflow: hidden;
}

.ghb-detail-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 22px 8px;
  flex-shrink: 0;
}

.ghb-detail-top > span {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ghb-detail-top button {
  padding: 5px;
  border-color: transparent;
}

.ghb-detail-tabs {
  display: flex;
  gap: 18px;
  padding: 0 22px;
  border-bottom: 1px solid var(--edge);
  flex-shrink: 0;
}

.ghb-detail-tabs button {
  border: 0;
  background: transparent;
  border-radius: 0;
  padding: 11px 0;
  color: var(--muted);
  font-size: 13px;
}

.ghb-detail-tabs button[aria-pressed="true"] {
  color: var(--text);
  box-shadow: 0 2px 0 var(--text);
}

.ghb-detail-tabs i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}

.ghb-detail-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: 20px 22px 24px;
  scrollbar-gutter: stable;
}

.ghb-item-header {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-bottom: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--edge);
}

.ghb-item-badges {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.ghb-kind-pill,
.ghb-state-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 600;
}

.ghb-kind-pill.is-pr {
  background: var(--pr-bg);
  color: var(--pr-color);
}
.ghb-kind-pill.is-issue {
  background: var(--issue-bg);
  color: var(--issue-color);
}
.ghb-kind-pill.is-draft {
  background: var(--panel);
  color: var(--muted);
}

.ghb-state-pill.is-open {
  background: var(--issue-bg);
  color: var(--issue-color);
}
.ghb-state-pill.is-closed {
  background: var(--panel);
  color: var(--muted);
}

.ghb-repo-ref {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11.5px;
  color: var(--muted);
}

.ghb-post {
  padding: 14px;
  border: 1px solid var(--edge);
  border-radius: 9px;
  background: var(--panel);
}

.ghb-post-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
  font-size: 12px;
}

.ghb-post-meta time {
  font-size: 11px;
  color: var(--muted);
}

.ghb-post pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font: inherit;
  font-size: 13.5px;
  line-height: 1.68;
  margin: 0;
}

.ghb-comments-head {
  margin: 20px 0 12px;
}

.ghb-comments-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 16px;
}

/* Organize & Draft Form */
.ghb-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.ghb-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 12px;
  min-width: 0;
}

.ghb-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.ghb-form :is(input, select, textarea) {
  width: 100%;
  min-width: 0;
  padding: 8px 11px;
  border: 1px solid var(--edge);
  border-radius: 7px;
  background: var(--surface);
  font-size: 13.5px;
}

.ghb-form textarea {
  resize: vertical;
  line-height: 1.6;
}

.ghb-draft-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.ghb-copy-btn {
  font-size: 11.5px;
  padding: 4px 9px !important;
}

.ghb-save {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 40px;
  position: sticky;
  bottom: -24px;
  background: var(--surface);
  padding: 12px 0;
  border-top: 1px solid var(--edge);
}

.ghb-save span {
  font-size: 11.5px;
  color: var(--muted);
}

.ghb-app .ghb-primary {
  background: var(--action);
  color: var(--on-action);
  border-color: var(--action);
}

/* Error Banner */
.ghb-alert {
  position: absolute;
  right: 20px;
  top: 64px;
  z-index: 40;
  width: min(460px, calc(100% - 40px));
  box-shadow: 0 4px 20px #0002;
  border-radius: 8px;
}

.ghb-error {
  max-width: 100%;
  border: 1px solid light-dark(#dfbaba, #704444);
  background: var(--surface-pop);
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 12px;
  overflow: hidden;
}

.ghb-detail .ghb-error {
  margin-bottom: 12px;
}

.ghb-error > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.ghb-error > div > strong {
  font-weight: 500;
}

.ghb-error button {
  padding: 4px 8px;
  font-size: 12px;
}

.ghb-error summary {
  cursor: pointer;
  padding: 5px 0 0;
  color: var(--muted);
}

.ghb-error textarea {
  margin-top: 10px;
  width: 100%;
  height: 124px;
  max-height: 160px;
  resize: none;
  font:
    12px/1.6 ui-monospace,
    monospace;
  color: var(--text);
  border: 1px solid var(--edge);
  border-radius: 5px;
  background: var(--panel);
  padding: 8px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.ghb-copy-row {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-top: 8px;
}

.ghb-copy-row span {
  font-size: 11px;
  color: var(--muted);
}

.ghb-spin {
  animation: ghb-spin 1.5s linear infinite;
}

@keyframes ghb-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 760px) {
  .ghb-app {
    padding: 12px;
  }
  .ghb-header {
    flex-wrap: wrap;
    gap: 8px;
  }
  .ghb-brand {
    flex: 1;
    min-width: 0;
  }
  .ghb-search {
    order: 5;
    flex: 1 1 100%;
    min-width: 0;
  }
  .ghb-workspace {
    grid-template-columns: 280px minmax(300px, 1fr);
  }
}

